def halton_qmc_area(p, n=200000):
    """D 的面积用确定性 Halton 点在对包围盒 [0,1]x[-1,1] 内打点估计（仅作量级对照）。"""
    def halton(i, b):
        f, r, k = 1.0, 0.0, i
        while k > 0:
            f /= b
            r += f * (k % b)
            k //= b
        return r
    cnt = 0
    for i in range(1, n + 1):
        x = halton(i, 2)
        y = -1.0 + 2.0 * halton(i, 3)
        if abs(x) ** p + abs(y) ** p + abs(x + y) ** p <= 1.0:
            cnt += 1
    return 2.0 * cnt / n


